1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import jakarta.validation.Valid;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
14	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
15	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
16	import org.springframework.validation.annotation.Validated;
17	import org.springframework.web.bind.annotation.RequestBody;
18	
19	@Validated
20	public class BuildOwner {
21	
22	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
23	            Out<Boolean> sharesHousehold)
24	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
25	            InvalidPostcodeException {
26	        // Publish the request-only 'sharesHousehold' flag for the household duplicate check.
27	        // Not part of the Owner entity, so it travels as a separate variable.
28	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
29	        // Normalize the address up front so the required-field check below rejects an address that
30	        // is blank once normalized, and every later comparison sees the stored normalized form.
31	        request.setAddress(Addresses.normalize(request.getAddress()));
32	        List<String> missing = new ArrayList<>();
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
38	        }
39	        if (isBlank(request.getAddress())) {
40	            missing.add("address");
41	        }
42	        if (isBlank(request.getCity())) {
43	            missing.add("city");
44	        }
45	        if (isBlank(request.getTelephone())) {
46	            missing.add("telephone");
47	        }
48	        if (!missing.isEmpty()) {
49	            throw new MissingOwnerFieldsException(missing);
50	        }
51	        // Normalize the telephone to E.164 form (keep '+'/country code, else assume '+61').
52	        request.setTelephone(Telephones.toE164(request.getTelephone()));
53	        // Email is optional; when present it must be syntactically valid and is stored lower-cased.
54	        request.setEmail(OwnerEmails.normalize(request.getEmail()));
55	        // Postcode is optional; when present it must be valid for the city's region
56	        // (a city with no known region accepts any 4-digit postcode). The 4-digit shape
57	        // is enforced by the request schema, so only the region range is checked here.
58	        Postcodes.validate(request.getCity(), request.getPostcode());
59	        Owner owner = ownerMapper.toOwner(request);
60	        // The effective registration date is the supplied value, or the server's current date when
61	        // none is supplied. Either way it must fall on a business day: a Saturday or Sunday rolls
62	        // forward to the next Monday. Everything derived from the registration date (membership
63	        // number year, daily create-limit) then sees this adjusted business day.
64	        LocalDate registrationDate = owner.getRegistrationDate();
65	        if (registrationDate == null) {
66	            registrationDate = LocalDate.now();
67	        }
68	        owner.setRegistrationDate(toBusinessDay(registrationDate));
69	        built.set(owner);
70	    }
71	
72	    /** Roll a weekend date forward to the next Monday; business days are returned unchanged. */
73	    private static LocalDate toBusinessDay(LocalDate date) {
74	        return switch (date.getDayOfWeek()) {
75	            case SATURDAY -> date.plusDays(2);
76	            case SUNDAY -> date.plusDays(1);
77	            default -> date;
78	        };
79	    }
80	
81	    private static boolean isBlank(String value) {
82	        return value == null || value.isBlank();
83	    }
84	}
