8	public class ApplyOwner {
9	
10	    public void service(@Val Owner owner, @Val OwnerFieldsDto request) throws InvalidPostcodeException {
11	        // Postcode is optional; when present it must be valid for the city's region.
12	        Postcodes.validate(request.getCity(), request.getPostcode());
13	        owner.setAddress(request.getAddress());
14	        owner.setCity(request.getCity());
15	        owner.setFirstName(request.getFirstName());
16	        owner.setLastName(request.getLastName());
17	        owner.setTelephone(request.getTelephone());
18	        owner.setEmail(request.getEmail());
19	        owner.setPostcode(request.getPostcode());
20	    }
21	}
