18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
42	    @Mapping(target = "identityKey",
43	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
44	    public abstract OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
48	     * present (non-null and non-blank), otherwise {@code PHONE}.
49	     */
50	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
51	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
52	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
53	    }
54	
55	    /**
56	     * Fixed city-to-region table: the owner's canonical region derived from its city.
57	     */
58	    static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
59	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
60	
61	    /**
62	     * Derives the owner's {@code locality} from its city using the fixed city-to-region
63	     * table ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), returning the canonical
64	     * region string, or {@code "UNKNOWN"} when the city is not in the table.
65	     */
66	    protected String locality(Owner owner) {
67	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
68	    }
69	
70	    /**
71	     * The membership level is capped at this value; level 4 is reserved for tenure.
72	     */
73	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
74	
75	    /**
76	     * Returns the owner's membership level, a number from 1 to
77	     * {@value #MAX_MEMBERSHIP_LEVEL} assigned at creation: it starts at 1, gains 1 when
78	     * an email address is present, gains 1 when the owner has no namesakes
79	     * (namesakeCount is 0), and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is
80	     * reserved for tenure).
81	     */
82	    public static int membershipLevel(Owner owner) {
83	        int level = 1;
84	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
85	        if (hasEmail) {
86	            level++;
87	        }
88	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
89	        if (noNamesakes) {
90	            level++;
91	        }
92	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
93	    }
94	
95	    /**
96	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
97	     * the registrationDate year (e.g. 'SMI-0007-M26'). Returns {@code null} when either the
98	     * customer code or the registration date is absent (e.g. legacy seed owners).
99	     */
100	    protected String membershipNumber(Owner owner) {
101	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
102	            return null;
103	        }
104	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
105	    }
106	
107	    /**
108	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
109	     * been created for this owner's {@code registrationDate}, using the same per-day
110	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
111	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
112	     */
113	    protected boolean bulkSignupWarning(Owner owner) {
114	        LocalDate registrationDate = owner.getRegistrationDate();
115	        if (registrationDate == null) {
116	            return false;
117	        }
118	        long count = ownerRepository.findAll().stream()
119	                .filter(existing -> !existing.getId().equals(owner.getId()))
120	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
121	                .count();
122	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
123	    }
124	
125	    public abstract Owner toOwner(OwnerDto ownerDto);
126	
127	    @Mapping(target = "id", ignore = true)
128	    @Mapping(target = "pets", ignore = true)
129	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
130	
131	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
132	
133	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
134	
135	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
136	        OwnerPageDto ownerPageDto = new OwnerPageDto();
137	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
138	        ownerPageDto.setPage(ownerPage.getNumber());
139	        ownerPageDto.setSize(ownerPage.getSize());
140	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
141	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
142	        return ownerPageDto;
143	    }
144	}
